import 'package:flutter/material.dart';import '../../../core/data/astro_repository.dart';import '../../../core/services/backup_service.dart';import '../../../core/services/static_content_service.dart';import '../../../core/services/reminder_service.dart';import '../../../core/theme/app_theme.dart';import '../../../shared/widgets/app_components.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{final url=TextEditingController();String status='Bundled content is available offline.';bool reminder=false,busy=false;TimeOfDay time=const TimeOfDay(hour:9,minute:0);
@override void initState(){super.initState();_load();}Future<void> _load()async{url.text=await AstroRepository.instance.setting('manifest_url')??'';reminder=(await AstroRepository.instance.setting('daily_reminder'))=='true';}
@override void dispose(){url.dispose();super.dispose();}
@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Settings',subtitle:'Your personal data stays on this device.'),const Text('Selected sun sign'),FutureBuilder<String>(future:AstroRepository.instance.selectedSign(),builder:(c,s)=>Text(s.data??'Loading…',style:const TextStyle(fontWeight:FontWeight.w700))),const SizedBox(height:18),Text('Public content source',style:Theme.of(context).textTheme.titleLarge),TextField(controller:url,decoration:const InputDecoration(hintText:'Public manifest URL')),const SizedBox(height:8),OutlinedButton(onPressed:()async{await AstroRepository.instance.setSetting('manifest_url',url.text.trim());setState(()=>status='Manifest URL saved.');},child:const Text('Save content URL')),FilledButton.tonalIcon(onPressed:busy?null:_refresh,icon:const Icon(Icons.sync),label:const Text('Check for updates')),Text(status,style:const TextStyle(color:AppTheme.muted,fontSize:12)),const Divider(height:30),Text('Daily reminder',style:Theme.of(context).textTheme.titleLarge),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Remind me each day'),subtitle:const Text('Optional local notification.'),value:reminder,onChanged:_toggleReminder),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Reminder time'),subtitle:Text(time.format(context)),trailing:const Icon(Icons.schedule),onTap:_pickTime),const Divider(height:30),Text('Backup and restore',style:Theme.of(context).textTheme.titleLarge),const Text('Export a JSON backup or import one from your device. Keep backups somewhere private.'),Wrap(spacing:8,children:[OutlinedButton.icon(onPressed:_export,icon:const Icon(Icons.ios_share),label:const Text('Export')),OutlinedButton.icon(onPressed:()=>_import(false),icon:const Icon(Icons.file_open),label:const Text('Import / merge')),OutlinedButton.icon(onPressed:()=>_import(true),icon:const Icon(Icons.restore),label:const Text('Import / replace'))]),const Divider(height:30),Text('Privacy and data',style:Theme.of(context).textTheme.titleLarge),const Text('No account, custom backend, Firebase or cloud sync. Birth details, selected sign, journal, favorites and reminders are not sent to public content hosts.'),OutlinedButton.icon(onPressed:_delete,icon:const Icon(Icons.delete_forever_outlined),label:const Text('Delete all local personal data')),const SizedBox(height:14),const DisclaimerCard()]);
Future<void> _refresh()async{if(url.text.trim().isEmpty){setState(()=>status='Enter a public manifest URL first.');return;}setState(()=>busy=true);try{final r=await StaticContentService().checkAndUpdate(Uri.parse(url.text.trim()));setState(()=>status='Validated and cached '+r.files.toString()+' files · '+r.version);}catch(e){setState(()=>status='Update failed; prior cached content was retained. '+e.toString());}finally{if(mounted)setState(()=>busy=false);}}
Future<void> _toggleReminder(bool v)async{if(v){final ok=await ReminderService.instance.requestPermission();if(!ok){setState(()=>status='Notification permission was not granted. App features remain available.');return;}await ReminderService.instance.scheduleDaily(hour:time.hour,minute:time.minute);}else{await ReminderService.instance.cancelDaily();}await AstroRepository.instance.setSetting('daily_reminder',v.toString());setState(()=>reminder=v);}
Future<void> _pickTime()async{final v=await showTimePicker(context:context,initialTime:time);if(v!=null){time=v;if(reminder)await ReminderService.instance.scheduleDaily(hour:v.hour,minute:v.minute);setState((){});}}
Future<void> _export()async{try{await BackupService().exportBackup();setState(()=>status='Backup share sheet opened.');}catch(e){setState(()=>status='Export failed: '+e.toString());}}
Future<void> _import(bool replace)async{try{final data=await BackupService().readBackup();if(data==null)return;final journal=data['journal'] as List;final saved=data['saved'] as List;final yes=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:Text(replace?'Replace local data?':'Merge backup?'),content:Text('Backup contains '+journal.length.toString()+' journal entries and '+saved.length.toString()+' favorites. '+(replace?'Existing local personal data will be replaced.':'Matching IDs will be updated; other local entries remain.')),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Import'))]));if(yes==true){await AstroRepository.instance.importAll(data,replace:replace);setState(()=>status='Backup imported successfully.');}}catch(e){setState(()=>status='Import failed: '+e.toString());}}
Future<void> _delete()async{final yes=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Delete local personal data?'),content:const Text('This permanently deletes favorites, journal, reading history, reminders and preferences.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Delete'))]));if(yes==true){await AstroRepository.instance.deletePersonalData();await ReminderService.instance.cancelDaily();setState(()=>status='Local personal data deleted.');}}
}
